func poorPigs(buckets int, minutesToDie int, minutesToTest int) int {
	times := minutesToTest / minutesToDie
	base := times + 1
	temp := math.Log(float64(buckets)) / math.Log(float64(base))
	ans := math.Ceil(temp)
	return int(ans)
}

class Solution {
  public int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
    int times = minutesToTest / minutesToDie;
    int base = times + 1;
    // base ^ ans >= buckets
    // ans >= log(buckets) / log(base)
    double temp = Math.log(buckets) / Math.log(base);
    int ans = (int) Math.ceil(temp);
    return ans;
  }
}

class Solution:

    def poorPigs(self, buckets: int, minutesToDie: int,
                 minutesToTest: int) -> int:
        base = minutesToTest / minutesToDie + 1
        return int(math.ceil(math.log10(buckets) / math.log10(base)))

impl Solution {
    pub fn poor_pigs(buckets: i32, minutes_to_die: i32, minutes_to_test: i32) -> i32 {
        let base = (minutes_to_test / minutes_to_die + 1) as f32;
        let buckets_f = buckets as f32;
        return (buckets_f.log10() / base.log10()).ceil() as i32;
    }
}

const poorPigs = (buckets: number, minutesToDie: number, minutesToTest: number): number => {
  const base = Math.floor(minutesToTest / minutesToDie) + 1;
  let ans = 0;
  let capacity = 1;
  while (capacity < buckets) {
    capacity *= base;
    ans++;
  }
  return ans;
};
